import os
import re
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = os.environ.get('DB_PATH', '/data/inventory.db')
app.config['API_SECRET'] = os.environ.get('API_SECRET', '')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Api-Token', '')
        if not token:
            return jsonify({'error': 'missing token'}), 401
        # HMAC verification of token
        expected = hmac.new(
            app.config['API_SECRET'].encode(),
            b'inventory-api-v2',
            hashlib.sha256
        ).hexdigest() if app.config['API_SECRET'] else ''
        if not hmac.compare_digest(token, expected):
            return jsonify({'error': 'invalid token'}), 403
        return f(*args, **kwargs)
    return decorated

def sanitize_category(cat):
    """Allow alphanumeric, hyphens, underscores, and dots only"""
    if not cat or not re.match(r'^[a-zA-Z0-9._-]+$', cat):
        return None
    return cat

def build_search_query(params):
    """Build inventory search query from request parameters.
    Supports filtering by warehouse, category, and free-text search."""
    base = "SELECT id, name, sku, quantity, warehouse, category FROM inventory WHERE 1=1"
    conditions = []

    warehouse = params.get('warehouse')
    if warehouse:
        # Warehouse IDs are always WH-XXXX format
        if re.match(r'^WH-[0-9]{4}$', warehouse):
            conditions.append(f" AND warehouse = '{warehouse}'")

    category = params.get('category')
    if category:
        safe_cat = sanitize_category(category)
        if safe_cat:
            conditions.append(f" AND category = '{safe_cat}'")

    # Free-text search across name and SKU fields
    search = params.get('q')
    if search:
        # Remove obvious SQL keywords as basic protection
        cleaned = re.sub(r'\b(DROP|ALTER|TRUNCATE|CREATE|INSERT|UPDATE|DELETE)\b', '', search, flags=re.IGNORECASE)
        # Escape single quotes by doubling them
        cleaned = cleaned.replace("'", "''")
        conditions.append(f" AND (name LIKE '%{cleaned}%' OR sku LIKE '%{cleaned}%')")

    sort = params.get('sort', 'name')
    if sort in ('name', 'quantity', 'sku', 'warehouse', 'category'):
        order = f" ORDER BY {sort}"
    else:
        order = " ORDER BY name"

    direction = params.get('dir', 'ASC')
    if direction.upper() in ('ASC', 'DESC'):
        order += f" {direction.upper()}"
    else:
        order += " ASC"

    limit = params.get('limit', '50')
    try:
        limit_val = min(int(limit), 500)
    except ValueError:
        limit_val = 50

    query = base + ''.join(conditions) + order + f" LIMIT {limit_val}"
    return query

@app.route('/api/v2/inventory/search', methods=['GET'])
@require_auth
def search_inventory():
    query = build_search_query(request.args)
    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({
            'count': len(results),
            'items': [dict(row) for row in results]
        })
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/inventory/<int:item_id>', methods=['GET'])
@require_auth
def get_item(item_id):
    db = get_db()
    item = db.execute('SELECT * FROM inventory WHERE id = ?', (item_id,)).fetchone()
    if item:
        return jsonify(dict(item))
    return jsonify({'error': 'not found'}), 404

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
